(()=>{const KEY='pino-workforce-v2-config';const defaultData={weeks:[{from:'2026-10-12',to:'2026-10-18',registration:false,assignment:true,final:false}],templates:[{code:'MORNING',name:'Ca sáng',start:'08:00',end:'12:00',active:true},{code:'AFTERNOON',name:'Ca chiều',start:'13:00',end:'17:00',active:true},{code:'EVENING',name:'Ca tối',start:'18:00',end:'21:00',active:true}]};let data=JSON.parse(localStorage.getItem(KEY)||'null')||defaultData;if(!data.weeks?.length)data.weeks=defaultData.weeks;if(!data.templates?.length)data.templates=defaultData.templates;let currentIndex=0,editing=-1;const $=id=>document.getElementById(id);function persist(){localStorage.setItem(KEY,JSON.stringify(data))}function dateStr(d){return d.toLocaleDateString('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric'})}function chooseWeek(i){currentIndex=Math.max(0,Math.min(data.weeks.length-1,i));let w=data.weeks[currentIndex];$('weekLabel').textContent=dateStr(new Date(w.from+'T12:00:00'))+' – '+dateStr(new Date(w.to+'T12:00:00'));window.weekOffset=Math.round((new Date(w.from)-new Date('2026-10-12'))/604800000);window.closed=!!w.final||!w.assignment;let btn=document.querySelector('.actions .primary');if(btn)btn.textContent=w.final?'Đã chốt':'Chốt tuần';$('wkStatus').textContent='Staff '+(w.registration?'mở':'đóng')+' · Xếp ca '+(w.assignment?'mở':'đóng');choose(...selected)}function moveWeek(delta){chooseWeek(currentIndex+delta)}function showModal(){refreshTemplates();$('templateModal').style.display='flex'}function hideModal(){$('templateModal').style.display='none'}function refreshTemplates(){let t=$('template');t.innerHTML=data.templates.filter(x=>x.active).map(x=>'<option value="'+x.start+','+x.end+'">'+x.name+' · '+x.start+'–'+x.end+'</option>').join('');$('templateRows').innerHTML=data.templates.map((x,i)=>'<div style="padding:12px;border-bottom:1px solid #413a4a;display:flex;justify-content:space-between;gap:12px"><div><b>'+x.name+'</b> <small>'+x.code+' · '+x.start+'–'+x.end+' · '+(x.active?'ACTIVE':'INACTIVE')+'</small></div><div><button onclick="window.editShift('+i+')">Sửa</button> <button onclick="window.toggleShift('+i+')">'+(x.active?'Ngừng':'Bật')+'</button></div></div>').join('')}window.editShift=i=>{editing=i;let x=data.templates[i];for(let k of ['code','name','start','end'])$('shift_'+k).value=x[k]};window.toggleShift=i=>{data.templates[i].active=!data.templates[i].active;persist();refreshTemplates()};window.saveShift=()=>{let x={};for(let k of ['code','name','start','end'])x[k]=$('shift_'+k).value.trim();x.code=x.code.toUpperCase();if(!x.code||!x.name||!x.start||!x.end||x.start>=x.end)return alert('Vui lòng nhập code, tên và giờ hợp lệ');if(editing<0&&data.templates.some(t=>t.code===x.code))return alert('Code đã tồn tại');x.active=editing<0?true:data.templates[editing].active;if(editing<0)data.templates.push(x);else data.templates[editing]=x;editing=-1;persist();refreshTemplates()};window.openTermWeek=()=>location.href='/termweek';window.openShiftModal=showModal;window.closeShiftModal=hideModal;window.changeWeek=moveWeek;window.toggleSettings=showModal;window.finalize=()=>{let w=data.weeks[currentIndex];if(w.final)return toast('Mở lại tuần từ module TermWeek để có lý do và audit');w.final=true;w.assignment=false;persist();chooseWeek(currentIndex);toast('Đã chốt tuần (prototype)')};const originalSave=window.save;window.save=()=>{let w=data.weeks[currentIndex];if(w.final||!w.assignment)return toast('Tuần đang khóa; quản lý trong TermWeek');originalSave()};$('template').addEventListener('change',e=>{let [s,t]=e.target.value.split(',');$('start').value=s;$('end').value=t});$('templateModal').addEventListener('click',e=>{if(e.target===$('templateModal'))hideModal()});let q=new URLSearchParams(location.search).get('termweek');let found=data.weeks.findIndex(w=>w.from===q);refreshTemplates();chooseWeek(found<0?0:found);})();